package ua.ukrainedrones

/**
 * Auto-generated post-2020 raion boundary polygons from OSM admin_level=6 relations
 * (Overpass), simplified to ~0.01 precision. Keys are (oblast stem, raion adjectival
 * name) matching CityRaions and NEPTUN's raion alert names — raion names repeat
 * across oblasts, so fills must scope by parent oblast. Used by MapView to shade the
 * alerting raion when "Fill alerting regions" is on and the alert is raion-level.
 * Regenerate with tools/gen_raion_boundaries.py.
 */
object RaionBoundaries {
    /** Rings for the raion, or null when unknown. [raionName] is case-insensitive.
     *  Each ring is a list of doubleArrayOf(lon, lat) pairs. */
    fun forKey(oblastStem: String, raionName: String): List<List<DoubleArray>>? =
        when (oblastStem) {
            "Івано-Франківськ" -> _Івано_Франківськ()[raionName.lowercase()]
            "Волинськ" -> _Волинськ()[raionName.lowercase()]
            "Вінницьк" -> _Вінницьк()[raionName.lowercase()]
            "Дніпропетровськ" -> _Дніпропетровськ()[raionName.lowercase()]
            "Донецьк" -> _Донецьк()[raionName.lowercase()]
            "Житомирськ" -> _Житомирськ()[raionName.lowercase()]
            "Закарпатськ" -> _Закарпатськ()[raionName.lowercase()]
            "Запорізьк" -> _Запорізьк()[raionName.lowercase()]
            "Київськ" -> _Київськ()[raionName.lowercase()]
            "Крим" -> _Крим()[raionName.lowercase()]
            "Кіровоградськ" -> _Кіровоградськ()[raionName.lowercase()]
            "Луганськ" -> _Луганськ()[raionName.lowercase()]
            "Львівськ" -> _Львівськ()[raionName.lowercase()]
            "Миколаївськ" -> _Миколаївськ()[raionName.lowercase()]
            "Одеськ" -> _Одеськ()[raionName.lowercase()]
            "Полтавськ" -> _Полтавськ()[raionName.lowercase()]
            "Рівненськ" -> _Рівненськ()[raionName.lowercase()]
            "Сумськ" -> _Сумськ()[raionName.lowercase()]
            "Тернопільськ" -> _Тернопільськ()[raionName.lowercase()]
            "Харківськ" -> _Харківськ()[raionName.lowercase()]
            "Херсонськ" -> _Херсонськ()[raionName.lowercase()]
